{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "No evidence-based treatment for COVID-19 currently exist to augment widely used supportive care protocols [7]. To control the growing COVID-19 pandemic, we rely on quarantine, isolation, and infection-control measures to prevent disease spread [7] and on supportive care, including oxygen and mechanical ventilation, for infected patients. Many randomized clinical trials assessing the effects of different potential treatments for COVID-19 are currently underway.",
      "reason": "Describes current state (no evidence-based treatments, reliance on supportive care and public health measures) and uncertainties (many trials underway indicating unanswered questions)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2) infection has spread rapidly worldwide, causing an international outbreak of the coronavirus disease 2019 (COVID-19). There is a need for a living systematic review evaluating the beneficial and harmful effects of all possible interventions for treatment of COVID-19.",
      "reason": "Explains the importance and need for the review (rapid global spread and explicit statement of need for a living systematic review to evaluate interventions)."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_33",
      "quote": "Wehave identified 4 important reviews that are comparable to our present project [77-80]. The first is a network meta-analysis just published in BMJ [77]. However, at the time of publication, this project did not include all relevant trials [50,52,54-56,59-61,64], including the pivotal trials assessing the effects of hydroxychloroquine [54,55,59]. The second project is a literature review published in JAMA ... Moreover, this review was only a narrative review without meta-analytic methods and trial sequential analysis [78]. The third project is a living mapping of ongoing randomized clinical trials with network meta-analysis on all interventions for COVID-19. ... This review includes both prevention and treatment and does not use trial sequential analysis or similar methods to handle problems with multiplicity ... The fourth project is a preprint of a rapid review ... These studies included patients with severe acute respiratory syndrome (SARS, n = 33), Middle East respiratory syndrome (MERS, n = 16), COVID-19 ( n = 3), and unspecified coronavirus (n = 2). ... The authors conclude that current evidence for the effectiveness and safety of antiviral therapies for COVID-19 is inconclusive and suffers from a lack of well-designed prospective trials. Moreover, this review was only a narrative review without meta-analytic methods and trial sequential analysis [9].",
      "reason": "Identifies and cites existing comparable reviews and explains differences/limitations of those reviews, justifying the need for the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence describes proposed mechanisms of action of the interventions assessed; the text focuses on disease spectrum, lack of treatments, and trial evidence rather than intervention mechanisms."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved evidence presents or refers to a logic model for complex interventions or delivery contexts; nothing in the provided text indicates a logic model was considered."
    }
  ],
  "confidence": "85"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "There is a need for a living systematic review evaluating the beneficial and harmful effects of all possible interventions for treatment of COVID-19.",
      "reason": "The manuscript explicitly states the objective to evaluate beneficial and harmful effects of interventions for COVID-19, but it does not present the objectives in a question-formulation framework (e.g., PICO) or as a clearly structured research question."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit planned comparisons framed using PICO (population, intervention, comparator, outcome) or an appropriate variant are provided in the retrieved evidence; outcomes are listed but specific PICO-style planned comparisons are not reported."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_2",
      "quote": "This is the first edition of a living systematic review of randomized clinical trials comparing the effects of all treatment interventions for participants in all age groups with COVID-19.",
      "reason": "The manuscript specifies eligible study design (randomized clinical trials) and participant populations (all age groups). It also indicates outcomes and that trial results at maximum follow-up were used (text_13). However, it does not fully specify other study characteristics such as settings (e.g., inpatient vs outpatient) or explicit follow-up duration requirements, so the eligibility characteristics are incompletely reported."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Trials were included irrespective of language, publication status, publication year, and publication type.",
      "reason": "The manuscript explicitly states eligibility criteria for report characteristics (language, publication status, year, and type)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported. The closest note describes one trial \"not eligible for meta-analysis, as the results were not reported in a usable way\" (text_22), but this does not constitute a general policy distinguishing the two reasons."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "We identified 8 trials comparing hydroxychloroquine added to standard care versus standard care alone [35,36,43,49,55,56,59,60]. We also identified one trial that used placebo as an additional control intervention [54].",
      "reason": "The review reports specific groups and comparisons used in syntheses (examples include hydroxychloroquine vs standard care, remdesivir vs placebo as noted elsewhere), indicating how some syntheses were grouped. However, it does not comprehensively present all groupings used in each synthesis or explicitly link each synthesis grouping to the comparisons defined in the review objectives, so reporting is incomplete."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit rationales are provided for notable restrictions on study eligibility (for example, the choice to include only randomized trials is not accompanied by an explicit rationale in the supplied evidence)."
    }
  ],
  "confidence": "80"
}

{
  "item_id": "PRISMA_2020_6",
  "elements": [
    {
      "element_id": "prisma_2020_6_e1",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "We searched all databases from their inception and until August 7, 2020.",
      "reason": "A date (August 7, 2020) is reported for the electronic database searches collectively, but last-search dates are not reported for other information sources (trial registries, websites, preprint servers, etc.)."
    },
    {
      "element_id": "prisma_2020_6_e2",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "An information specialist searched the Cochrane Central Register of Controlled Trials (CENTRAL) in The Cochrane Library, Medical Literature Analysis and Retrieval System Online (MEDLINE Ovid), Excerpta Medica database (Embase Ovid), Latin American and Caribbean Health Sciences Literature (LILACS; Bireme), Science Citation Index Expanded (SCI-EXPANDED; Web of Science), Conference Proceedings Citation Index-Science (CPCI-S; Web of Science), BIOSIS (Web of Science), CINAHL (EBSCO host), Chinese Biomedical Literature Database (CBM), China Network Knowledge Information (CNKI), Chinese Science Journal Database (VIP), and Wafang Database to identify relevant trials. We searched all databases from their inception and until August 7, 2020.",
      "reason": "Names of many bibliographic databases and some platforms/search interfaces (e.g., MEDLINE Ovid, Embase Ovid, CINAHL (EBSCO host), CENTRAL in The Cochrane Library, Web of Science indices) are reported and coverage is stated as 'from their inception' to Aug 7, 2020; however, a platform or interface is not specified for every listed database (e.g., Wafang) and per-source coverage details are not given individually."
    },
    {
      "element_id": "prisma_2020_6_e3",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "To identify unpublished trials, we searched clinical trial registries (e.g., clinicaltrials.gov, clinicaltrialregister.eu, who.int/ictrp, chictr.org.cn) of Europe, USA, and China, and websites of pharmaceutical companies, websites of US Food and Drug Administration (FDA) and European Medicines Agency (EMA). We also searched the COVID-19 Study Registry [13] and the real-time dashboard of randomized trials [14].",
      "reason": "Names of several trial registers and registries are provided, but no information on any date restrictions or the last-search dates specific to these registers is reported."
    },
    {
      "element_id": "prisma_2020_6_e4",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "To identify unpublished trials, we searched ... websites of pharmaceutical companies, websites of US Food and Drug Administration (FDA) and European Medicines Agency (EMA). We also searched the COVID-19 Study Registry [13] and the real-time dashboard of randomized trials [14]. We also searched preprint servers (bioRxiv, medRxiv) for unpublished trials.",
      "reason": "Several websites and online sources (FDA, EMA, COVID-19 Study Registry, real-time dashboard, bioRxiv, medRxiv) are named, but explicit URLs are not provided for these sources and full search-method details for each online source/URL are not reported."
    },
    {
      "element_id": "prisma_2020_6_e5",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "To identify unpublished trials, we searched ... websites of pharmaceutical companies, websites of US Food and Drug Administration (FDA) and European Medicines Agency (EMA). ... We contacted all trial authors to obtain individual patient data.",
      "reason": "The authors report searching websites of pharmaceutical companies and regulatory bodies (FDA, EMA) and state they contacted all trial authors, but do not name specific organisations or manufacturers that were contacted to identify studies."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "We contacted all trial authors if relevant data were unclear or missing.",
      "reason": "The types of individuals contacted are specified (trial authors)."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "The reference lists of relevant trial publications were checked for any unidentified randomized clinical trials.",
      "reason": "The authors specify that they examined reference lists of relevant trial publications."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_9",
      "quote": "The reference lists of relevant trial publications were checked for any unidentified randomized clinical trials.",
      "reason": "The report describes checking reference lists but does not report performing backward or forward citation searching (no seed reports, citation index/platform, or citation search dates are provided); thus this specific item (detailed backward/forward citation searching) does not apply based on the presented methods."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "An information specialist searched the Cochrane Central Register of Controlled Trials (CENTRAL) in The Cochrane Library, ... Conference Proceedings Citation Index-Science (CPCI-S; Web of Science) ... We searched all databases from their inception and until August 7, 2020.",
      "reason": "Conference proceedings/index (CPCI-S) is named as searched and coverage period for databases including this index is stated ('from their inception' to Aug 7, 2020), meeting the requirement to report journals/conference proceedings source names and dates covered."
    }
  ],
  "confidence": 80
}

