{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Primary and secondary outcomes were predefined in our protocol [9]. Primary outcomes were all-cause mortality and serious adverse events (as defined by the International Conference on Harmonation-Good Clinical Practice [ICH-GCP] guidelines) [9,16]. Secondary outcomes were admission to intensive care (as defined by trialists), receipt of mechanical ventilation (as defined by trialists), receipt of renal replacement therapy (as defined by trialists), quality of life, and nonserious adverse events. We classified nonserious adverse events as any adverse event not assessed as serious according to the ICH-GCP definition.",
      "reason": "The manuscript explicitly lists primary and secondary outcome domains and provides definitions for serious and nonserious adverse events."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "For all outcomes, we used the trial results reported at maximum follow-up.",
      "reason": "The time frame of measurement for outcomes is specified as the trial results at maximum follow-up."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "For all outcomes, we used the trial results reported at maximum follow-up.",
      "reason": "The manuscript states they used results at maximum follow-up (indicating a selection rule), but does not explicitly state whether they sought all results compatible with each outcome domain (e.g., all measures, all time points, all analyses) prior to applying that selection."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "For all outcomes, we used the trial results reported at maximum follow-up.",
      "reason": "A clear process for selecting results is described: when multiple results exist, the trial result at maximum follow-up was used."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "PARTIAL",
      "chunk_id": "text_35",
      "quote": "Further, we included 'time to clinical improvement' as an outcome post hoc.",
      "reason": "A change to outcomes (addition of a post hoc outcome) is reported, but no rationale for this change is provided in the cited text."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was provided describing changes to the processes for selecting results within eligible outcome domains or any rationale for such changes."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": "We assessed a total of 2 primary outcomes, and we therefore adjusted our thresholds for significance [18] and considered a p -value of 0.033 or less as the threshold for statistical significance [9,18]. Because we primarily considered results of secondary outcomes as hypothesis generating, we did not adjust the p -value for secondary outcomes.",
      "reason": "The manuscript identifies the two primary outcomes and describes adjusting significance thresholds and treating secondary outcomes as hypothesis-generating, which indicates prioritisation, but it does not explicitly state a broader rationale for why these outcomes were deemed most important beyond statistical adjustment."
    }
  ],
  "confidence": "80"
}

